/**
 * Metadata shared between route segments.
 *
 * A child segment *replaces* the parent's whole `openGraph` object instead of
 * merging into it (see "Merging" in the Next.js `generateMetadata` docs), and
 * that replacement also drops the card generated by `app/opengraph-image.js`.
 * So any segment declaring its own `openGraph` has to spread these back in —
 * without them the page ships with no social image at all, which is how
 * `/resume` ended up pointing at a `profile.jpg` that never existed.
 *
 * The URL is relative on purpose: `metadataBase` in the root layout resolves it.
 */
export const SOCIAL_IMAGES = [
    {
        url: "/opengraph-image",
        width: 1200,
        height: 630,
        alt: "Baptiste Dubillaud — Tech-Lead & AI Software Engineer",
    },
];
